def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # A vertical 5-bar copies the colored strip attached to its right upward.
    for c in range(w):
        rows = [r for r in range(h) if g[r][c] == 5]
        if len(rows) < 2 or rows != list(range(min(rows), max(rows)+1)):
            continue
        top, bottom = min(rows), max(rows)
        # The seed is the contiguous colored tile touching the bar at its lower end.
        if c+1 >= w or g[bottom][c+1] in (0,5):
            continue
        lo = bottom
        while lo > 0 and g[lo-1][c+1] not in (0,5):
            lo -= 1
        hi = bottom
        while hi+1 < h and g[hi+1][c+1] not in (0,5):
            hi += 1
        width = 0
        while c+1+width < w and all(g[r][c+1+width] not in (0,5) for r in range(lo,hi+1)):
            width += 1
        if width == 0: continue
        tile = [[g[r][c+1+j] for j in range(width)] for r in range(lo,hi+1)]
        th = len(tile)
        for r in range(top, bottom+1):
            if r >= lo: continue
            pat = tile[(r-lo) % th]
            for j,val in enumerate(pat):
                if g[r][c+1+j] == 0: g[r][c+1+j] = val
    # A horizontal 5-bar copies the vertical colored strip beneath its left end rightward.
    for r in range(h):
        cols = [c for c in range(w) if g[r][c] == 5]
        runs=[]
        for c in cols:
            if not runs or c != runs[-1][-1]+1: runs.append([c])
            else: runs[-1].append(c)
        for run in runs:
            if len(run) < 2: continue
            left, right = run[0], run[-1]
            if r+1 >= h or g[r+1][left] in (0,5): continue
            lo = r+1
            hi = lo
            while hi+1 < h and g[hi+1][left] not in (0,5): hi += 1
            tile = [g[q][left] for q in range(lo,hi+1)]
            for c in range(left+1,right+1):
                for i,val in enumerate(tile):
                    q=lo+i
                    if g[q][c] == 0: g[q][c]=val
    return g
